"""Interrupt the real write-set publisher and its automatic rollback for recovery tests."""
from contextlib import nullcontext
from pathlib import Path
from unittest.mock import patch

from scripts.core.jsonio import read_json
from scripts.core.locks import project_lock_reentrant
from scripts.core.write_sets import apply_write_set


def interrupted_write_set(root: Path, outputs: dict[str, bytes | None], *, phase='prepared',
                          relative=None, lock_held=False) -> dict:
    """Leave exactly the durable manifest/images generated by apply_write_set.

    Interrupting rollback models a second failure after publication was interrupted.
    No manifest format or before/after hash is manufactured by the fixture.
    lock_held is only used inside the lock-acquisition race seam after O_EXCL won.
    """
    directory = root/'.govel/transactions'
    prior = set(directory.glob('*.json'))

    def crash(at, path=None):
        if at == phase and (relative is None or path == relative):
            raise KeyboardInterrupt('injected publisher interruption')

    held = nullcontext() if lock_held else project_lock_reentrant(root)
    with held, patch('scripts.core.write_sets.checkpoint', side_effect=crash), \
            patch('scripts.core.write_sets.recover_write_set', side_effect=KeyboardInterrupt('rollback interrupted')):
        try:
            apply_write_set(root, outputs, operation='recovery_fixture')
        except OSError as exc:
            if 'rollback incomplete' not in str(exc):
                raise
        else:
            raise AssertionError('the selected write-set interruption did not occur')
    manifests = set(directory.glob('*.json')) - prior
    if len(manifests) != 1:
        raise AssertionError(f'expected one real interrupted write set, found {len(manifests)}')
    manifest = read_json(manifests.pop())
    if manifest['schemaVersion'] != 2:
        raise AssertionError('write-set publisher emitted an unexpected recovery protocol')
    return manifest


def assert_preserved_rollback(case, root: Path, before: dict, after: dict) -> None:
    """Business bytes stay OLD; new archives must prove a completed rollback."""
    import hashlib
    from scripts.core.finalization import pending_transactions
    prefix = '.govel/transactions/'
    business = lambda rows: {str(key): value for key, value in rows.items()
                             if not str(key).startswith(prefix)}
    case.assertEqual(business(before), business(after))
    case.assertEqual(pending_transactions(root), [])
    old_archives = {str(key): value for key, value in before.items() if str(key).startswith(prefix)}
    for key, value in old_archives.items():
        case.assertEqual(after[key], value, 'existing transaction evidence must remain unchanged')
    new_terminals = [root / str(key) for key in after if str(key).startswith(prefix)
                     and str(key).endswith('/completed.json') and key not in before]
    case.assertTrue(new_terminals, 'failed write must leave its actual rollback archive')
    for terminal in new_terminals:
        manifest = read_json(terminal)
        case.assertEqual(manifest['phase'], 'rolled_back')
        for row in manifest['files']:
            target = root/row['path']
            case.assertEqual(target.is_file(), row['before']['exists'])
            if row['before']['exists']:
                case.assertEqual(hashlib.sha256(target.read_bytes()).hexdigest(), row['before']['sha256'])
            for side in ('before', 'after'):
                if row[side]['exists']:
                    image = terminal.parent/side/row['path']
                    case.assertEqual(hashlib.sha256(image.read_bytes()).hexdigest(), row[side]['sha256'])
